    private string? _maTruongBo;
    private string? _selectedNamHoc;
    private string? _selectedCapHoc;

    private List<KhoiHoc_DTO>  _khoiList    = new();
    private List<LopHoc_DTO>   _allLopList  = new();
    private List<LopHoc_DTO>   _lopFiltered = new();
    private int    _selKhoiId = 0;
    private string _selMaLop  = "";
    private string _selTenLop = "";
    private int    _selLopId  = 0;

    // Data
    private List<ScnTheoDoiTienBoDTO> _data    = new();
    private List<HocSinhDTO>          _hsList  = new();

    // Search
    private string _searchText = "";
    private IEnumerable<ScnTheoDoiTienBoDTO> _displayData =>
        string.IsNullOrWhiteSpace(_searchText) ? _data
        : _data.Where(x =>
            (x.HoTen?.Contains(_searchText, StringComparison.OrdinalIgnoreCase) == true) ||
            (x.MaHsSo?.Contains(_searchText, StringComparison.OrdinalIgnoreCase) == true) ||
            (_hsList.FirstOrDefault(h => h.MaHsSo == x.MaHsSo)?.MaBo?.Contains(_searchText, StringComparison.OrdinalIgnoreCase) == true));

    // Modal
    private bool _showModal = false;
    private ScnTheoDoiTienBoDTO _editItem = new();
    private Dictionary<string, string> _valErrors = new();

    // Delete
    private ScnTheoDoiTienBoDTO? _deleteTarget = null;

    private bool _isLoading = false;
    private bool _isSaving  = false;

    private string _toastMsg = "", _toastCss = "", _toastIcon = "";
    private System.Threading.CancellationTokenSource? _toastCts;

    protected override async Task OnInitializedAsync()
    {
        _maTruongBo     = await BrowserStorageService.GetMaTruongBoAsync(JS);
        _selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
        _selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");

        var tk = TruongService.hGetDanhSachKhoi(_maTruongBo ?? "", _selectedCapHoc ?? "1");
        var tl = TruongService.hGetDanhSachLop(_maTruongBo ?? "", _selectedCapHoc ?? "1", _selectedNamHoc ?? "");
        await Task.WhenAll(tk, tl);
        _khoiList   = tk.Result;
        _allLopList = tl.Result;

        if (_khoiList.Any())
        {
            _selKhoiId   = _khoiList[0].MaKhoi;
            _lopFiltered = _allLopList.Where(l => l.MaKhoi == _selKhoiId).ToList();
        }
        else _lopFiltered = _allLopList.ToList();

        if (_lopFiltered.Any())
        {
            _selMaLop  = _lopFiltered[0].MaLopBo;
            _selTenLop = _lopFiltered[0].TenLop;
            _selLopId  = _lopFiltered[0].IdLopBo;
            await LoadData();
        }
    }

    private async Task OnKhoiChanged(ChangeEventArgs e)
    {
        _selKhoiId   = int.TryParse(e.Value?.ToString(), out var v) ? v : 0;
        _lopFiltered = _selKhoiId == 0 ? _allLopList.ToList()
                       : _allLopList.Where(l => l.MaKhoi == _selKhoiId).ToList();
        if (_lopFiltered.Any())
        {
            _selMaLop  = _lopFiltered[0].MaLopBo;
            _selTenLop = _lopFiltered[0].TenLop;
            _selLopId  = _lopFiltered[0].IdLopBo;
        }
        else { _selMaLop = ""; _selTenLop = ""; _selLopId = 0; }
        _searchText = "";
        if (!string.IsNullOrEmpty(_selMaLop)) await LoadData();
    }

    private async Task OnLopChanged(ChangeEventArgs e)
    {
        _selMaLop = e.Value?.ToString() ?? "";
        var lop  = _lopFiltered.FirstOrDefault(l => l.MaLopBo == _selMaLop);
        _selTenLop = lop?.TenLop ?? "";
        _selLopId  = lop?.IdLopBo ?? 0;
        _searchText = "";
        if (!string.IsNullOrEmpty(_selMaLop)) await LoadData();
    }

    private async Task LoadData()
    {
        if (string.IsNullOrEmpty(_selMaLop)) return;
        _isLoading = true; StateHasChanged();
        try
        {
            var t1 = TruongService.hGetTheoDoiTienBo(
                lopId:  _selLopId > 0 ? _selLopId  : (int?)null,
                namHoc: _selectedNamHoc ?? "");
            var t2 = TruongService.hGetHocSinhByLop(
                matruongbo: _maTruongBo ?? "",
                malop:      _selMaLop,
                namhoc:     _selectedNamHoc ?? "");
            await Task.WhenAll(t1, t2);
            _data   = t1.Result;
            _hsList = t2.Result;
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error"); }
        finally { _isLoading = false; StateHasChanged(); }
    }

    // ── MODAL ──
    private void OpenAdd()
    {
        _editItem  = new ScnTheoDoiTienBoDTO
        {
            KhoiId = _selKhoiId > 0 ? _selKhoiId : (int?)null,
            LopId  = _selLopId  > 0 ? _selLopId  : (int?)null,
            NamHoc = _selectedNamHoc ?? ""
        };
        _valErrors = new();
        _showModal = true;
    }

    private void OpenEdit(ScnTheoDoiTienBoDTO item)
    {
        _editItem = new ScnTheoDoiTienBoDTO
        {
            Id             = item.Id,
            KhoiId         = item.KhoiId,
            LopId          = item.LopId,
            MaHsSo         = item.MaHsSo,
            HoTen          = item.HoTen,
            // Strip HTML trước khi đưa vào textarea – data cũ lưu bằng Quill
            NoiDungLuuY    = StripHtml(item.NoiDungLuuY),
            BienPhapGiupDo = StripHtml(item.BienPhapGiupDo),
            KetQua         = StripHtml(item.KetQua),
            NamHoc         = item.NamHoc
        };
        _valErrors = new();
        _showModal = true;
    }

    private void CloseModal() => _showModal = false;

    private void OnSelectHocSinh(ChangeEventArgs e)
    {
        var maHsSo = e.Value?.ToString() ?? "";
        var hs = _hsList.FirstOrDefault(h => h.MaHsSo == maHsSo);
        _editItem.MaHsSo = maHsSo;
        _editItem.HoTen  = hs?.HoTen ?? "";
    }

    private async Task SaveModal()
    {
        _valErrors = new();
        // Validation
        if (string.IsNullOrWhiteSpace(_editItem.MaHsSo))
            _valErrors["hocsinh"] = "Vui lòng chọn học sinh";
        if (string.IsNullOrWhiteSpace(_editItem.NoiDungLuuY))
            _valErrors["noidung"] = "Vui lòng nhập nội dung cần lưu ý";
        if (string.IsNullOrWhiteSpace(_editItem.BienPhapGiupDo))
            _valErrors["bienphap"] = "Vui lòng nhập biện pháp giúp đỡ";
        if (string.IsNullOrWhiteSpace(_editItem.KetQua))
            _valErrors["ketqua"] = "Vui lòng nhập kết quả";

        if (_valErrors.Any()) { StateHasChanged(); return; }

        _isSaving = true; StateHasChanged();
        try
        {
            _editItem.KhoiId = _selKhoiId > 0 ? _selKhoiId : (int?)null;
            _editItem.LopId  = _selLopId  > 0 ? _selLopId  : (int?)null;
            _editItem.NamHoc = _selectedNamHoc ?? "";

            await TruongService.hUpsertTheoDoiTienBo(_editItem);
            await LoadData();
            _showModal = false;
            await ShowToast(
                _editItem.Id > 0 ? "Đã cập nhật theo dõi!" : "Đã thêm học sinh theo dõi!",
                "toast-ok", "check_circle");
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error"); }
        finally { _isSaving = false; StateHasChanged(); }
    }

    // ── DELETE ──
    private async Task DoDelete()
    {
        if (_deleteTarget == null) return;
        _isSaving = true; StateHasChanged();
        try
        {
            await TruongService.hDeleteTheoDoiTienBo(_deleteTarget.Id);
            _deleteTarget = null;
            await LoadData();
            await ShowToast("Đã xoá!", "toast-ok", "check_circle");
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error"); }
        finally { _isSaving = false; StateHasChanged(); }
    }

    // ── HELPERS ──
    private static string GetInitials(string? name)
    {
        if (string.IsNullOrEmpty(name)) return "?";
        var parts = name.Trim().Split(' ', StringSplitOptions.RemoveEmptyEntries);
        if (parts.Length == 1) return parts[0][0].ToString().ToUpper();
        return $"{parts[0][0]}{parts[^1][0]}".ToUpper();
    }

    // Strip HTML Quill → plaintext (dùng khi mở textarea sửa)
    private static string StripHtml(string? html)
    {
        if (string.IsNullOrEmpty(html)) return "";
        html = System.Text.RegularExpressions.Regex.Replace(html, @"<br\s*/?>", "\n",
               System.Text.RegularExpressions.RegexOptions.IgnoreCase);
        html = System.Text.RegularExpressions.Regex.Replace(html, @"</p>", "\n",
               System.Text.RegularExpressions.RegexOptions.IgnoreCase);
        html = System.Text.RegularExpressions.Regex.Replace(html, @"<[^>]+>", "");
        html = html.Replace("&nbsp;", " ").Replace("&amp;", "&")
                   .Replace("&lt;", "<").Replace("&gt;", ">")
                   .Replace("&quot;", "\"");
        return html.Trim();
    }

    private async Task ShowToast(string msg, string css, string icon)
    {
        _toastCts?.Cancel();
        _toastCts = new System.Threading.CancellationTokenSource();
        _toastMsg = msg; _toastCss = css; _toastIcon = icon;
        StateHasChanged();
        try { await Task.Delay(3500, _toastCts.Token); _toastMsg = ""; StateHasChanged(); }
        catch (TaskCanceledException) { }
    }

